import { ChefHat} from "lucide-react";

function Header() {
  return (
    <header className="bg-white border-b h-20 flex items-center px-6">
      <div className="flex-1 text-left">
        <h1 className="text-xl font-semibold">Left</h1>
      </div>
      <div className="flex-1 text-center">
        <h1 className="text-xl font-semibold">Center</h1>
      </div>
      <div className="flex-1 text-right">
        <h1 className="text-xl font-semibold">Right</h1>
      </div>
    </header>
  );
}

export default Header;
